文件：Tasks.tsx
上下文：点击按钮应立即在列表中新增一个任务。
代码：
```tsx
import { useState } from 'react';
export function Tasks() {
  const [items, setItems] = useState<string[]>([]);
  function add() {
    items.push('新任务');
    setItems(items);
  }
  return <><button onClick={add}>新增</button><p>{items.join(',')}</p></>;
}
```

文件：Clock.tsx
上下文：组件会多次挂载和卸载，卸载后不应继续计时。
代码：
```tsx
import { useEffect, useState } from 'react';
export function Clock() {
  const [ticks, setTicks] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTicks(n => n + 1), 1000);
  }, []);
  return <p>{ticks}</p>;
}
```

文件：PageTitle.tsx
上下文：父组件会更新 title，浏览器标题应同步显示当前值。
代码：
```tsx
import { useEffect } from 'react';
export function PageTitle({ title }: { title: string }) {
  useEffect(() => {
    document.title = title;
  }, []);
  return <h1>{title}</h1>;
}
```

文件：Scores.tsx
上下文：同一个 scores 数组还被父组件用于显示原始顺序。
代码：
```tsx
export function Scores({ scores }: { scores: number[] }) {
  const sorted = scores.sort((a, b) => b - a);
  return <p>{sorted.join(',')}</p>;
}
```

文件：ProductPhoto.tsx
上下文：图片承担展示商品名称的用途，附近没有商品名称文字，读屏用户也需要知道商品名称。
代码：
```tsx
export function ProductPhoto({ src, name }: { src: string; name: string }) {
  return <img src={src} />;
}
```

